/// How long we wait for a daemon we spawned (or one already coming up) to accept connections.
const DAEMON_CONNECT_TIMEOUT: Duration = Duration::from_secs(5);
/// Poll interval while waiting for the socket to become connectable.
const DAEMON_CONNECT_POLL: Duration = Duration::from_millis(50);

/// Idle cadence for the foreground `attach-tab` live tab-strip refresh. The renderer-event listener
/// blocks on `recv_timeout(LIVE_TAB_STRIP_REFRESH_INTERVAL)`; a real renderer event preempts the wait
/// immediately, so this is only the maximum staleness before an EXTERNAL change (another process
/// writing persisted attention, tab metadata edits, recomputed task-derived `needs_attention`) becomes
/// visible. Conservative on purpose: long enough that an idle renderer does no meaningful work, short
/// enough to feel live. Each tick is a local records-only rebuild with change detection — no daemon
/// call, no command unless the strip actually changed.
const LIVE_TAB_STRIP_REFRESH_INTERVAL: Duration = Duration::from_millis(750);
/// Background/stashed sessions have no renderer attachment to forward their typed exit event.
/// Reconcile the daemon's live set at a bounded low cadence so dashboard status converges, live
/// sessions without panes remain actionable, and ordinary focus never silently relaunches an ended
/// session. This runs off the existing listener tick (no GUI/event-loop heartbeat) and never
/// persists the daemon endpoint on each pass.
const SESSION_STATUS_RECONCILE_INTERVAL: Duration = Duration::from_secs(2);

/// Fast wake cadence for the renderer-event listener. Each wake does only CHEAP checks (the remote
/// focus-request file + one `PRAGMA data_version` read on the cached connection); the heavy tick body
/// (strip rebuild, self-heal model diff, enrollment check) still runs at
/// `LIVE_TAB_STRIP_REFRESH_INTERVAL` cadence — EXCEPT when `data_version` shows a second local
/// process committed to the store, which triggers the full body immediately. Net effect: a
/// remote mutation (browser create/delete of a project/window/pane) reaches the local sidebar/topbar
/// within ~250ms instead of waiting out the slow tick.
const LISTENER_TICK_INTERVAL: Duration = Duration::from_millis(250);

/// Maximum time a foreground renderer path waits for its app-side event listener to retire after
/// the GUI has returned. The listener normally observes the explicit stop flag within one
/// [`LISTENER_TICK_INTERVAL`]; this wider bound protects process teardown from an unexpected stuck
/// handler without coupling daemon/session retention to a UI helper thread.
const WINDOW_EVENT_LISTENER_SHUTDOWN_TIMEOUT: Duration = Duration::from_secs(2);

/// Default expanded width of the left dock column, in logical pixels. The dock reserves this much
/// horizontal space on the left edge; the terminal grid insets to its right and the shell's PTY
/// column count is reduced in lockstep (via `window_dims`) so output reflows to the narrower width.
const DOCK_DEFAULT_WIDTH_PX: u32 = 268;

/// Width of the COLLAPSED left-dock icon rail, in logical pixels: wide enough for a centered project
/// icon plus the collapse-toggle button, narrow enough to give most of the width back to the grid. Fed
/// to `build_dock_model` (and thus the renderer's X inset) exactly like the expanded width, so the grid
/// reclaims the difference in lockstep when the dock collapses.
const DOCK_RAIL_WIDTH_PX: u32 = 24;

/// The dock width to project for a given collapsed state: the thin rail when collapsed, the full column
/// when expanded. Single source so every dock rebuild picks the matching width.
fn dock_width_for(collapsed: bool) -> u32 {
    if collapsed {
        DOCK_RAIL_WIDTH_PX
    } else {
        DOCK_DEFAULT_WIDTH_PX
    }
}

/// Project one app-side [`SettingsPanelRow`] into its renderer-side mirror. Display-only and
/// field-for-field: it copies the already-sanitized/bounded `id`/`category`/`label`/`value` plus the
/// `setting_key`/`editable` metadata, owning the strings (the app row borrows `&'static str` for the
/// stable fields). It moves NO settings authority into the renderer — `setting_key` stays descriptive
/// metadata that the renderer does not act on.
fn settings_panel_row_to_renderer(
    row: &maestro_app::SettingsPanelRow,
) -> maestro_renderer::RendererSettingsPanelRow {
    maestro_renderer::RendererSettingsPanelRow {
        id: row.id.to_string(),
        category: row.category.to_string(),
        label: row.label.to_string(),
        value: row.value.clone(),
        setting_key: row.setting_key.map(|k| k.to_string()),
        editable: row.editable,
    }
}

/// Build the renderer top-panel carrier for the settings panel, carrying the bounded/sanitized
/// `lines` AND the structured `settings_rows` projected from the SAME app projection. Used by all
/// three foreground settings-panel paths (command-palette `settings.show_panel`, the settings
/// shortcut, and launch-time `--settings-panel`) so they cannot drift. Display-only: it reuses the
/// existing `RendererDashboardPanel` carrier and adds no executable/mutation surface — the rows are
/// metadata describing the lines, and the visible panel still draws from `lines`.
fn settings_panel_to_renderer(
    panel_lines: &maestro_app::SettingsPanelLines,
) -> maestro_renderer::RendererDashboardPanel {
    let rows = panel_lines
        .rows
        .iter()
        .map(settings_panel_row_to_renderer)
        .collect();
    maestro_renderer::RendererDashboardPanel::settings_with_rows(panel_lines.lines.clone(), rows)
}

/// Max characters retained from a row id or setting key when composing the activation feedback
/// label. Stable metadata should already be short; this is a defensive cap so a malformed/oversized
/// id can never blow up the single-line status label.
const SETTINGS_ACTIVATION_ID_CAP: usize = 64;

/// Sanitize a stable row id / setting key for inclusion in the single-line status label: drop any
/// control characters (so it cannot inject newlines or terminal escapes into the status row) and cap
/// the length. Pure; the inputs should already be stable, this just guarantees the bound.
fn sanitize_settings_activation_fragment(raw: &str) -> String {
    raw.chars()
        .filter(|c| !c.is_control())
        .take(SETTINGS_ACTIVATION_ID_CAP)
        .collect()
}

/// Compose the visible, display-only status label shown when Enter ACTIVATES a settings-panel row.
/// This is feedback only — it changes no setting and opens no editor/prompt. It preserves the base
/// status identity prefix and appends, after a ` · ` separator, a bounded single-line message that
/// distinguishes an editable row (editing is pending / not yet implemented) from a read-only row.
///
/// A row is treated as editable only when `editable` AND a `setting_key` is present; otherwise it is
/// read-only. Only stable metadata is used (`row_id`, optional `setting_key`, `editable`) — never row
/// label/value text, settings JSON, paths, or argv — and both the id and key are sanitized/length-
/// capped even though they should already be stable.
fn settings_panel_activation_status_label(
    base: &str,
    row_id: &str,
    setting_key: Option<&str>,
    editable: bool,
) -> String {
    let id = sanitize_settings_activation_fragment(row_id);
    match (editable, setting_key) {
        (true, Some(key)) => {
            let key = sanitize_settings_activation_fragment(key);
            format!("{base} · settings: {id} ({key}) editing not yet available")
        }
        _ => format!("{base} · settings: {id} is read-only"),
    }
}

/// Map a settings key to the [`ChromeDefaultKey`] it persists, for the chrome boolean keys whose
/// edit-draft submit is allowed to WRITE. Any other key returns `None` and keeps the
/// validation-only / not-saved behavior even when its draft value would parse.
fn settings_panel_writable_chrome_key(setting_key: &str) -> Option<ChromeDefaultKey> {
    match setting_key {
        "chrome.top_tab_bar_default" => Some(ChromeDefaultKey::TopTabBar),
        "chrome.dashboard_status_default" => Some(ChromeDefaultKey::DashboardStatus),
        "chrome.dashboard_panel_default" => Some(ChromeDefaultKey::DashboardPanel),
        "chrome.picker_overlay_default" => Some(ChromeDefaultKey::PickerOverlay),
        _ => None,
    }
}

/// Outcome of app-side revalidation of a submitted settings edit draft. The app does NOT trust the
/// renderer as the persistence authority: it re-checks both the key (the four chrome boolean keys plus
/// `appearance.theme` / `appearance.font_size_px` are writable) and the value (a boolean,
/// a recognized theme id, or an in-range font-size integer) before any write.
#[derive(Debug, Clone, PartialEq, Eq)]
enum SettingsPanelSubmitPlan {
    /// The submit targets a writable chrome boolean key and its value re-validated as a boolean.
    /// Carries the target key and parsed bool to persist.
    WriteChromeBool(ChromeDefaultKey, bool),
    /// The submit targets `appearance.theme` and its value re-validated as a supported theme id.
    /// Carries the validated theme identifier to persist via `set_theme`.
    WriteTheme(String),
    /// The submit targets `appearance.font_size_px` and its value re-validated as an in-range integer.
    /// Carries the parsed pixel size to persist via `set_font_size_px`.
    WriteFontSize(u32),
    /// The submit targets `shell.default_argv` and its value re-validated as a JSON array of strings
    /// with a non-empty first command. Carries the parsed argv to persist via `set_shell_default_argv`.
    WriteShellArgv(Vec<String>),
    /// The submit targets `workspace.default_policy` and its value re-validated as a supported policy
    /// id. Carries the validated policy to persist via `set_workspace_default_policy`.
    WriteWorkspacePolicy(String),
    /// The submit targets a writable `workspace.*_requires_consent` boolean key and its value
    /// re-validated as a boolean. Carries the target key and parsed bool to persist.
    WriteWorkspaceConsent(WorkspaceConsentKey, bool),
    /// The submit targets a writable key but the value did not re-validate.
    InvalidValue,
    /// The submit targets a key that is not writable.
    UnsupportedKey,
}

/// Re-validate a submitted settings edit draft APP-SIDE. Pure and unit-testable: it never writes,
/// reads config, or contacts the renderer. Accepts the four chrome boolean keys
/// ([`settings_panel_writable_chrome_key`], parsing case-insensitive `true`/`false`), `appearance.theme`
/// (validated via [`validate_theme`]), and `appearance.font_size_px` (parsed and range-checked via
/// [`validate_font_size_px`]), and `shell.default_argv` (validated via
/// [`validate_shell_default_argv`]). Any other key is
/// [`SettingsPanelSubmitPlan::UnsupportedKey`]; a bad value for a writable key is
/// [`SettingsPanelSubmitPlan::InvalidValue`].
fn plan_settings_panel_submit(setting_key: &str, value: &str) -> SettingsPanelSubmitPlan {
    let trimmed = value.trim();
    if let Some(chrome_key) = settings_panel_writable_chrome_key(setting_key) {
        return if trimmed.eq_ignore_ascii_case("true") {
            SettingsPanelSubmitPlan::WriteChromeBool(chrome_key, true)
        } else if trimmed.eq_ignore_ascii_case("false") {
            SettingsPanelSubmitPlan::WriteChromeBool(chrome_key, false)
        } else {
            SettingsPanelSubmitPlan::InvalidValue
        };
    }
    match setting_key {
        "appearance.theme" => match validate_theme(trimmed) {
            Ok(theme) => SettingsPanelSubmitPlan::WriteTheme(theme),
            Err(_) => SettingsPanelSubmitPlan::InvalidValue,
        },
        "appearance.font_size_px" => match trimmed.parse::<u32>() {
            Ok(px) if validate_font_size_px(px).is_ok() => {
                SettingsPanelSubmitPlan::WriteFontSize(px)
            }
            _ => SettingsPanelSubmitPlan::InvalidValue,
        },
        "shell.default_argv" => match validate_shell_default_argv(trimmed) {
            Ok(argv) => SettingsPanelSubmitPlan::WriteShellArgv(argv),
            Err(_) => SettingsPanelSubmitPlan::InvalidValue,
        },
        "workspace.default_policy" => match validate_workspace_policy(trimmed) {
            Ok(policy) => SettingsPanelSubmitPlan::WriteWorkspacePolicy(policy),
            Err(_) => SettingsPanelSubmitPlan::InvalidValue,
        },
        "workspace.worktree_requires_consent" => {
            plan_workspace_consent(WorkspaceConsentKey::WorktreeRequiresConsent, trimmed)
        }
        "workspace.repo_write_requires_consent" => {
            plan_workspace_consent(WorkspaceConsentKey::RepoWriteRequiresConsent, trimmed)
        }
        _ => SettingsPanelSubmitPlan::UnsupportedKey,
    }
}

/// Re-validate a `workspace.*_requires_consent` submit value as a case-insensitive `true`/`false`,
/// returning the write plan or [`SettingsPanelSubmitPlan::InvalidValue`].
fn plan_workspace_consent(key: WorkspaceConsentKey, trimmed: &str) -> SettingsPanelSubmitPlan {
    if trimmed.eq_ignore_ascii_case("true") {
        SettingsPanelSubmitPlan::WriteWorkspaceConsent(key, true)
    } else if trimmed.eq_ignore_ascii_case("false") {
        SettingsPanelSubmitPlan::WriteWorkspaceConsent(key, false)
    } else {
        SettingsPanelSubmitPlan::InvalidValue
    }
}

/// Bounded status label shown after a settings-panel submit attempt. Pure and unit-testable. The
/// key fragment is sanitized; reasons are short fixed literals so nothing unbounded leaks.
fn settings_panel_submit_status_label(
    base: &str,
    setting_key: &str,
    outcome: SettingsPanelSubmitOutcome<'_>,
) -> String {
    let key = sanitize_settings_activation_fragment(setting_key);
    match outcome {
        SettingsPanelSubmitOutcome::Saved => format!("{base} · settings: {key} saved"),
        SettingsPanelSubmitOutcome::InvalidValue => {
            let hint = match setting_key {
                "appearance.theme" => "expected a supported theme",
                "appearance.font_size_px" => "expected an in-range integer",
                "shell.default_argv" => "expected a JSON array of strings",
                "workspace.default_policy" => "expected a supported workspace policy",
                _ => "expected true or false",
            };
            format!("{base} · settings: {key} not saved ({hint})")
        }
        SettingsPanelSubmitOutcome::UnsupportedKey => {
            format!("{base} · settings: {key} not saved (not editable here)")
        }
        SettingsPanelSubmitOutcome::WriteFailed(reason) => {
            let reason = sanitize_settings_activation_fragment(reason);
            format!("{base} · settings: {key} not saved ({reason})")
        }
    }
}

/// Bounded outcome kinds for [`settings_panel_submit_status_label`].
#[derive(Debug, Clone, Copy)]
enum SettingsPanelSubmitOutcome<'a> {
    Saved,
    InvalidValue,
    UnsupportedKey,
    WriteFailed(&'a str),
}

const MAX_REACT_CHROME_INTENT_BYTES: usize = 64 * 1024;
const MAX_REACT_CHROME_STRING_BYTES: usize = 16 * 1024;
const MAX_REACT_CHROME_ARRAY_ITEMS: usize = 256;
const MAX_REACT_CHROME_OBJECT_FIELDS: usize = 64;
const MAX_REACT_CHROME_JSON_DEPTH: usize = 8;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReactChromeIntentDecodeError {
    TooLarge,
    Malformed,
    ShapeLimit,
}

impl ReactChromeIntentDecodeError {
    fn code(self) -> &'static str {
        match self {
            Self::TooLarge => "intent_too_large",
            Self::Malformed => "intent_malformed",
            Self::ShapeLimit => "intent_shape_limit",
        }
    }
}

fn react_chrome_json_shape_is_bounded(value: &serde_json::Value, depth: usize) -> bool {
    if depth > MAX_REACT_CHROME_JSON_DEPTH {
        return false;
    }
    match value {
        serde_json::Value::Null | serde_json::Value::Bool(_) | serde_json::Value::Number(_) => true,
        serde_json::Value::String(value) => value.len() <= MAX_REACT_CHROME_STRING_BYTES,
        serde_json::Value::Array(values) => {
            values.len() <= MAX_REACT_CHROME_ARRAY_ITEMS
                && values
                    .iter()
                    .all(|value| react_chrome_json_shape_is_bounded(value, depth + 1))
        }
        serde_json::Value::Object(values) => {
            values.len() <= MAX_REACT_CHROME_OBJECT_FIELDS
                && values.keys().all(|key| key.len() <= 128)
                && values
                    .values()
                    .all(|value| react_chrome_json_shape_is_bounded(value, depth + 1))
        }
    }
}

fn react_chrome_allowed_fields(intent_type: &str) -> Option<&'static [&'static str]> {
    Some(match intent_type {
        "dashboardTinyInitProbe" | "dashboardPreloadBareProbe" => {
            &["has_ipc", "has_webkit_ipc", "href", "ready_state"]
        }
        "dashboardPostLoadEvalProbe" => &[
            "has_ipc",
            "has_webkit_ipc",
            "has_host",
            "href",
            "ready_state",
        ],
        "dashboardPreloadReady" => &["has_ipc", "href", "ready_state"],
        "dashboardBundleLoaded" => &["has_host", "has_ipc", "href"],
        "dashboardOverlayReady"
        | "cancelStashedPaneDrag"
        | "removeRemote"
        | "openAvailableUpdate"
        | "openFullDiskAccessSettings"
        | "refreshDesktopAccess"
        | "openProjectDialog"
        | "closeOverlay"
        | "focusTerminal" => &[],
        "applyRemoteFilesystemMigration" | "acknowledgeRemoteFilesystemMigration" => &["notice_id"],
        "pickProjectFolder" => &["request_id"],
        "listFolderSessions" | "listHiddenFolderSessions" => &["request_id", "agent", "cwd"],
        "cancelFolderSessionRequest" | "cancelFolderSessionPreview" => &["request_id"],
        "previewFolderSession"
        | "hideFolderSession"
        | "deleteFolderSession"
        | "unhideFolderSession" => &["request_id", "agent", "cwd", "session_id"],
        "setFolderSessionName" => &["request_id", "agent", "cwd", "session_id", "name"],
        "openWorkspace" => &["project_id", "workspace_id"],
        "preflightLaunch" => &["request_id", "agent", "resolved_launch_command", "cwd"],
        "createProject" => &[
            "name",
            "root",
            "icon",
            "accent_color",
            "default_agent",
            "default_model",
            "resume_mode",
            "dangerous_skip_permissions",
            "custom_command",
            "resolved_launch_command",
            "resume_session_id",
            "resume_session_title",
            "resume_session_file",
            "extra_folders",
            "create_initial_session",
        ],
        "updateProject" => &["project_id", "name", "root", "icon", "accent_color"],
        "deleteProject" => &[
            "project_id",
            "remove_record",
            "keep_working_directory",
            "close_open_windows",
        ],
        "createWindow" => &[
            "project_id",
            "name",
            "root",
            "agent",
            "model",
            "session_mode",
            "resume_session_id",
            "resume_session_title",
            "resume_session_file",
            "resolved_launch_command",
        ],
        "focusWindow" | "stashWindow" | "removeWindow" => &["project_id", "window_id"],
        "saveLayoutPreset" => &["project_id", "window_id", "preset_id", "name"],
        "openLayoutPreset" => &["project_id", "preset_id", "window_id"],
        "updateWindow" => &["project_id", "window_id", "name", "root"],
        "updatePane" => &["project_id", "window_id", "tab_id", "name"],
        "stashPane" | "removePane" => &["project_id", "window_id", "tab_id"],
        "beginStashedPaneDrag" | "focusSessionOrPane" => {
            &["project_id", "window_id", "tab_id", "session_id"]
        }
        "moveStashedPaneDrag" | "completeStashedPaneDrop" => &["x", "y"],
        "reviveSession" => &["session_id", "window_id", "tab_id"],
        "splitPane" => &[
            "project_id",
            "window_id",
            "tab_id",
            "dir",
            "agent",
            "resume_session_id",
            "resume_session_title",
            "resume_session_file",
            "resolved_launch_command",
            "pane_name",
            "cwd",
        ],
        "openSplitDialog" => &["project_id", "window_id", "tab_id", "dir"],
        "setRemoteAccess" => &["open"],
        "enrollDesktop" => &["code"],
        "openEditProjectDialog" | "openWindowDialog" => &["project_id"],
        "setSidebarWidth" => &["width"],
        "updateProjectOrder" => &["ordered_project_ids"],
        "updateWindowOrder" => &["project_id", "ordered_window_ids"],
        "dashboardRuntimeError" => &["message", "source", "line"],
        _ => return None,
    })
}

fn parse_react_chrome_intent(
    json: &str,
) -> Result<ReactChromeIntent, ReactChromeIntentDecodeError> {
    if json.len() > MAX_REACT_CHROME_INTENT_BYTES {
        return Err(ReactChromeIntentDecodeError::TooLarge);
    }
    let value: serde_json::Value =
        serde_json::from_str(json).map_err(|_| ReactChromeIntentDecodeError::Malformed)?;
    if !react_chrome_json_shape_is_bounded(&value, 0) {
        return Err(ReactChromeIntentDecodeError::ShapeLimit);
    }
    let object = value
        .as_object()
        .ok_or(ReactChromeIntentDecodeError::Malformed)?;
    let intent_type = object
        .get("type")
        .and_then(serde_json::Value::as_str)
        .ok_or(ReactChromeIntentDecodeError::Malformed)?;
    let allowed =
        react_chrome_allowed_fields(intent_type).ok_or(ReactChromeIntentDecodeError::Malformed)?;
    if object
        .keys()
        .any(|key| key != "type" && !allowed.contains(&key.as_str()))
    {
        return Err(ReactChromeIntentDecodeError::Malformed);
    }
    serde_json::from_value(value).map_err(|_| ReactChromeIntentDecodeError::Malformed)
}

