    #[test]
    fn submit_arm_writes_every_chrome_boolean_and_refreshes_then_clears_draft() {
        // Each of the four chrome boolean keys persists through the existing settings path, refreshes
        // the panel, clears the draft, and sends a bounded saved status carrying that key.
        for key in [
            "chrome.top_tab_bar_default",
            "chrome.dashboard_status_default",
            "chrome.dashboard_panel_default",
            "chrome.picker_overlay_default",
        ] {
            let tmp = tempfile::tempdir().expect("tempdir");
            let base = tmp.path();
            let (mut tab_runtime, tab_commands) = RendererTabRuntime::new();

            run_submit_arm(&mut tab_runtime, base, "session • shell", key, "true");

            let chrome = effective_settings(base).chrome;
            let persisted = match key {
                "chrome.top_tab_bar_default" => chrome.top_tab_bar_default,
                "chrome.dashboard_status_default" => chrome.dashboard_status_default,
                "chrome.dashboard_panel_default" => chrome.dashboard_panel_default,
                "chrome.picker_overlay_default" => chrome.picker_overlay_default,
                other => panic!("unexpected key {other}"),
            };
            assert!(persisted, "{key} persisted true through set_chrome_default");
            // Panel refresh.
            assert!(
                matches!(
                    tab_commands.try_recv(),
                    Ok(maestro_renderer::RendererCommand::SetDashboardPanel { dashboard_panel })
                        if dashboard_panel.is_some()
                ),
                "{key} refreshes the panel first"
            );
            // Draft clear.
            assert!(
                matches!(
                    tab_commands.try_recv(),
                    Ok(maestro_renderer::RendererCommand::SetSettingsPanelEditDraft { draft })
                        if draft.is_none()
                ),
                "{key} clears the draft second"
            );
            // Saved status carrying the key.
            match tab_commands.try_recv() {
                Ok(maestro_renderer::RendererCommand::SetStatusLabel { status_label }) => {
                    let label = status_label.expect("saved status present");
                    assert!(
                        label.contains(key) && label.contains("saved"),
                        "{key} saved feedback: {label:?}"
                    );
                }
                other => panic!("expected SetStatusLabel(Some) third for {key}, got {other:?}"),
            }
            assert!(
                tab_commands.try_recv().is_err(),
                "{key} sends exactly panel, draft-clear, saved-status and nothing else"
            );
        }
    }

