    #[test]
    fn submit_arm_closed_channel_is_nonfatal() {
        // A closed renderer command channel during the saved-status/refresh sends is non-fatal: the
        // typed RendererControlClosed surfaces (the listener logs and swallows it) rather than
        // panicking. The write itself still persisted.
        let tmp = tempfile::tempdir().expect("tempdir");
        let base = tmp.path();

        let (mut tab_runtime, rx) = RendererTabRuntime::new();
        drop(rx); // renderer event loop gone.

        // Reproduce only the write + first send so we can assert the send surfaces a typed error
        // rather than panicking. The write must persist regardless of the dead channel.
        set_chrome_default(base, ChromeDefaultKey::TopTabBar, true).expect("write persists");
        let panel =
            settings_panel_to_renderer(&build_settings_panel_lines(&effective_settings(base)));
        let err = tab_runtime
            .set_dashboard_panel(Some(panel))
            .expect_err("closed channel surfaces a typed error on the refresh send");
        assert!(
            matches!(err, maestro_app::TabSwitchError::RendererControlClosed),
            "a closed channel is a typed non-fatal error, got {err:?}"
        );
        assert!(
            effective_settings(base).chrome.top_tab_bar_default,
            "the write persisted even though the renderer channel was closed"
        );
    }

    /// A READ-ONLY activation keeps the read-only status feedback AND clears any pending draft, sending
    /// exactly one `SetStatusLabel(Some(..))` (read-only) plus one `SetSettingsPanelEditDraft(None)`,
    /// and NO mutating/session/tab/window command — and never an edit-draft `Some`.
