    /// `settings.show` executes read-only and dismisses, but it does NOT open the settings panel: the
    /// only commands are the result then the dismiss — never a `SetDashboardPanel`.
    #[test]
    fn settings_show_activation_sends_no_panel_command() {
        let (mut tab_runtime, tab_commands) = RendererTabRuntime::new();
        let base = std::env::temp_dir();

        let outcome = run_command_palette_action_activation("settings.show", Some(base.clone()));
        assert!(
            command_palette_activation_should_dismiss(&outcome),
            "settings.show is the read-only Executed success case"
        );
        assert!(
            !command_palette_activation_opens_settings_panel(&outcome),
            "settings.show must NOT open the settings panel"
        );

        let result = command_palette_activation_result(&outcome);
        tab_runtime
            .set_command_palette_result(Some(result))
            .expect("result command sends");
        if command_palette_activation_opens_settings_panel(&outcome) {
            let panel_lines = build_settings_panel_lines(&effective_settings(&base));
            let panel = settings_panel_to_renderer(&panel_lines);
            tab_runtime
                .set_dashboard_panel(Some(panel))
                .expect("panel command sends");
        }
        if command_palette_activation_should_dismiss(&outcome) {
            tab_runtime
                .dismiss_command_palette()
                .expect("dismiss command sends");
        }

        // Result, then dismiss — and NO panel command anywhere.
        assert!(matches!(
            tab_commands.try_recv(),
            Ok(maestro_renderer::RendererCommand::SetCommandPaletteResult { .. })
        ));
        assert!(matches!(
            tab_commands.try_recv(),
            Ok(maestro_renderer::RendererCommand::DismissCommandPalette)
        ));
        assert!(
            tab_commands.try_recv().is_err(),
            "settings.show sends exactly the result then the dismiss — never a panel command"
        );
    }

