    #[test]
    fn explicit_reopen_accepts_known_safe_and_canonical_legacy_provider_but_not_raw_adhoc() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path().join("base"));
        let mut target = seed_user_target(&paths, tmp.path());
        let fallback = vec!["fallback-shell".to_string()];
        target.session.status = SessionStatus::Exited;

        target.session.launch = LaunchSpec::KnownSafe {
            launch_spec_id: "codex".into(),
            params: vec!["resume".into(), "session-one".into()],
        };
        let known_safe = authorized_product_restart_argv_with_authority(
            &paths,
            &target,
            &fallback,
            ProductRestartAuthority::ExplicitUserRestart,
        )
        .unwrap()
        .expect("explicit reopen authorizes exited KnownSafe");
        assert_eq!(known_safe[0], super::login_shell_program());
        assert!(known_safe[2].contains("codex") && known_safe[2].contains("session-one"));

        target.session.launch = LaunchSpec::AdHocRedacted {
            argv: vec![
                "codex".into(),
                "resume".into(),
                "provider-session".into(),
                "--secret-token".into(),
                "must-not-survive".into(),
            ],
            redacted: false,
            restart_requires_user: true,
        };
        target.session.kind = SessionKind::Agent;
        let legacy_provider = authorized_product_restart_argv_with_authority(
            &paths,
            &target,
            &fallback,
            ProductRestartAuthority::ExplicitUserRestart,
        )
        .unwrap()
        .expect("exact legacy provider is reduced to a canonical recipe");
        assert_eq!(legacy_provider[0], super::login_shell_program());
        assert!(
            legacy_provider[2].contains("codex") && legacy_provider[2].contains("provider-session")
        );
        assert!(!legacy_provider[2].contains("secret-token"));

        for argv in [
            vec!["custom-command".into(), "safe-argument".into()],
            vec!["codex".into()],
            vec![
                "wrapper".into(),
                "codex".into(),
                "resume".into(),
                "provider-session".into(),
            ],
            vec![
                "agent".into(),
                "--resume".into(),
                uuid::Uuid::new_v4().to_string(),
            ],
        ] {
            target.session.launch = LaunchSpec::AdHocRedacted {
                argv,
                redacted: false,
                restart_requires_user: true,
            };
            assert!(authorized_product_restart_argv_with_authority(
                &paths,
                &target,
                &fallback,
                ProductRestartAuthority::ExplicitUserRestart,
            )
            .unwrap()
            .is_none());
        }

        for launch in [
            LaunchSpec::AdHocRedacted {
                argv: vec!["redacted-command".into()],
                redacted: true,
                restart_requires_user: true,
            },
            LaunchSpec::AdHocRedacted {
                argv: vec!["legacy-command".into()],
                redacted: false,
                restart_requires_user: false,
            },
        ] {
            target.session.launch = launch;
            assert!(authorized_product_restart_argv_with_authority(
                &paths,
                &target,
                &fallback,
                ProductRestartAuthority::ExplicitUserRestart,
            )
            .unwrap()
            .is_none());
        }
    }

