    #[test]
    fn fresh_daemon_recovery_selects_live_and_exact_exited_safe_recipes_once() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path().join("base"));
        let base = seed_user_target(&paths, tmp.path());

        let mut safe = base.clone();
        safe.session.session_id = "safe-live".into();
        safe.session.kind = SessionKind::Agent;
        safe.session.status = SessionStatus::Live;
        safe.session.launch = LaunchSpec::KnownSafe {
            launch_spec_id: "claude".into(),
            params: vec!["--resume".into(), "provider-session".into()],
        };
        let mut exited = safe.clone();
        exited.session.session_id = "safe-exited".into();
        exited.session.status = SessionStatus::Exited;
        let mut exited_latest = exited.clone();
        exited_latest.session.session_id = "safe-exited-latest".into();
        exited_latest.session.launch = LaunchSpec::KnownSafe {
            launch_spec_id: "claude".into(),
            params: vec!["--continue".into()],
        };
        let mut adhoc = safe.clone();
        adhoc.session.session_id = "adhoc-live".into();
        adhoc.session.launch = LaunchSpec::AdHocRedacted {
            argv: vec!["claude".into()],
            redacted: false,
            restart_requires_user: true,
        };
        let duplicate = safe.clone();

        let (candidates, declined) = daemon_loss_recovery_candidates(
            &paths,
            vec![safe, exited, exited_latest, adhoc, duplicate],
            "already-opened",
            &["sh".into()],
        )
        .unwrap();
        assert_eq!(
            candidates
                .iter()
                .map(|target| target.session.session_id.as_str())
                .collect::<Vec<_>>(),
            ["safe-live", "safe-exited"]
        );
        assert_eq!(declined, 2, "duplicate ids are ignored, not double-counted");
    }

    #[test]
    fn fresh_daemon_recovery_restarts_exact_exited_provider_with_v2_authority() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path().join("base"));
        let target = seed_exited_exact_claude_target(&paths, tmp.path());
        let socket = tmp.path().join("fresh-recovery.sock");
        let listener = UnixListener::bind(&socket).unwrap();
        let session_id = target.session.session_id.clone();
        let expected_id = session_id.clone();
        let server = std::thread::spawn(move || {
            {
                let (mut stream, _) = listener.accept().unwrap();
                let mut reader = std::io::BufReader::new(stream.try_clone().unwrap());
                let mut request = String::new();
                reader.read_line(&mut request).unwrap();
                assert_eq!(
                    serde_json::from_str::<serde_json::Value>(&request).unwrap()["op"],
                    "attach"
                );
                let message =
                    serde_json::to_string(&format!("no such session: {expected_id}")).unwrap();
                writeln!(stream, "{{\"ev\":\"error\",\"message\":{message}}}").unwrap();
                stream.flush().unwrap();
            }

            let (mut stream, _) = listener.accept().unwrap();
            let mut reader = std::io::BufReader::new(stream.try_clone().unwrap());
            let mut request = String::new();
            reader.read_line(&mut request).unwrap();
            assert_eq!(request.trim(), r#"{"op":"daemon_info"}"#);
            writeln!(
                stream,
                "{{\"ev\":\"daemon_info\",\"protocol_version\":{},\"build_version\":\"test\"}}",
                maestro_protocol::DAEMON_PROTOCOL_VERSION
            )
            .unwrap();
            stream.flush().unwrap();

            request.clear();
            reader.read_line(&mut request).unwrap();
            let start: serde_json::Value = serde_json::from_str(&request).unwrap();
            assert_eq!(start["op"], "start_session");
            assert_eq!(start["id"], expected_id);
            let command_line = start["args"]
                .as_array()
                .and_then(|args| args.last())
                .and_then(serde_json::Value::as_str)
                .expect("login-shell command line");
            assert!(command_line.contains("'claude' '--resume' 'provider-session-123'"));
            assert_eq!(start["restart_exited"], true);

            request.clear();
            reader.read_line(&mut request).unwrap();
            assert_eq!(
                serde_json::from_str::<serde_json::Value>(&request).unwrap()["op"],
                "attach"
            );
            let id = serde_json::to_string(&expected_id).unwrap();
            writeln!(
                stream,
                "{{\"ev\":\"grid\",\"id\":{id},\"grid\":{{\"generation\":\"after-reboot\",\"revision\":1}}}}"
            )
            .unwrap();
            stream.flush().unwrap();
        });

        let mode = open_one_product_target(
            &paths,
            &socket,
            &target,
            &["sh".into()],
            ProductRestartAuthority::FreshDaemonRecovery,
            21,
        )
        .expect("fresh recovery should complete")
        .expect("exact provider should be selected");
        assert!(matches!(mode, LaunchSessionMode::Started(_)));
        server.join().unwrap();
        let recovered: SessionRecord =
            loaded(&paths, RecordKind::Session, &target.session.session_id);
        assert_eq!(recovered.status, SessionStatus::Live);
        assert_eq!(
            recovered.last_known_generation.as_deref(),
            Some("after-reboot")
        );
    }

    #[test]
    fn all_hidden_and_stashed_topology_uses_hidden_fixed_recovery_without_revive() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let paths = AppPaths::with_base(tmp.path().join("base"));
        ensure_product_startup_target(&paths, 1).expect("stable seed");
        let windows = WindowLayoutService::new(&paths);
        windows
            .set_tab_stashed(SYSTEM_TERMINAL_WINDOW_ID, SYSTEM_TERMINAL_TAB_ID, true, 2)
            .unwrap();
        let projects = ProjectService::new(&paths);
        let mut stable_project = projects.load(SYSTEM_TERMINAL_PROJECT_ID).unwrap().unwrap();
        stable_project.hidden = true;
        store::write_record(
            &paths,
            RecordKind::Project,
            SYSTEM_TERMINAL_PROJECT_ID,
            3,
            &stable_project,
        )
        .unwrap();

        let first = ensure_product_startup_target(&paths, 4).expect("recovery target");
        let second = ensure_product_startup_target(&paths, 5).expect("same recovery target");
        assert_eq!(first.project_id, PRODUCT_RECOVERY_PROJECT_ID);
        assert_eq!(first.layout.window_id, PRODUCT_RECOVERY_WINDOW_ID);
        assert_eq!(first.tab_id, PRODUCT_RECOVERY_TAB_ID);
        assert_eq!(first.session.session_id, PRODUCT_RECOVERY_SESSION_ID);
        assert_eq!(second.layout.window_id, first.layout.window_id);
        assert!(
            projects
                .load(PRODUCT_RECOVERY_PROJECT_ID)
                .unwrap()
                .unwrap()
                .hidden
        );
        assert!(
            projects
                .load(SYSTEM_TERMINAL_PROJECT_ID)
                .unwrap()
                .unwrap()
                .hidden
        );
        assert!(
            windows
                .load(SYSTEM_TERMINAL_WINDOW_ID)
                .unwrap()
                .unwrap()
                .tabs
                .iter()
                .find(|tab| tab.tab_id == SYSTEM_TERMINAL_TAB_ID)
                .unwrap()
                .stashed
        );
        assert_eq!(
            store::load_all::<SessionRecord>(&paths, RecordKind::Session)
                .unwrap()
                .len(),
            2,
            "fixed recovery session must not duplicate"
        );
    }

